# 4.7 — truy cập từ xa: TerminalServices-LocalSessionManager 21/22/23/24/25/39/40, RemoteConnectionManager 1149, Security 4778/4779/4825, tscon (chiếm phiên).
# Mẫu: tc/rdp-21-25.evtx (Yamato Security, máy EC2 thật 11/2024), tc/rdp-hijack-4778-4779.evtx + tc/rdp-1149-nhieu-may.evtx + tc/rdp-4825.evtx (EVTX-to-MITRE-Attack).
@ps evtx-rec tc/rdp-21-25.evtx | ConvertFrom-Json | Group-Object id | Select-Object Count,@{n='Id';e={$_.Name}} | Format-Table -AutoSize
@ps evtx-rec tc/rdp-21-25.evtx | ConvertFrom-Json | Where-Object { $_.id -in 21,22,23,24,25,39,40 -and $_.t -ge [datetime]'2024-11-22T22:36:00Z' } | ForEach-Object { '{0}  {1,-3} phiên={2,-2} {3,-31} {4}' -f $_.t.ToString('HH:mm:ss'), $_.id, $_.data.SessionID, $_.data.User, $_.data.Address } | Select-Object -First 40
@ps evtx-rec tc/rdp-21-25.evtx | ConvertFrom-Json | Where-Object id -eq 40 | Group-Object { $_.data.Reason } | Select-Object Count,@{n='Reason';e={$_.Name}} | Format-Table -AutoSize
@ps evtx-rec tc/rdp-hijack-4778-4779.evtx | ConvertFrom-Json | Where-Object { $_.id -in 4778,4779 -or $_.data.CommandLine -match 'tscon' } | ForEach-Object { '{0}  {1}  {2}' -f $_.t.ToString('HH:mm:ss.fff'), $_.id, $(if ($_.id -eq 4688) { $_.data.SubjectUserName + ' chạy: ' + $_.data.CommandLine } else { '{0}\{1} phiên {2} máy {3} ({4})' -f $_.data.AccountDomain, $_.data.AccountName, $_.data.SessionName, $_.data.ClientName, $_.data.ClientAddress }) }
@ps evtx-rec tc/rdp-hijack-4778-4779.evtx | ConvertFrom-Json | Where-Object { $_.data.CommandLine -match 'tscon' } | Select-Object -First 1 | ForEach-Object { $_.data | Format-List SubjectUserName,SubjectLogonId,NewProcessName,CommandLine,TokenElevationType,ParentProcessName,MandatoryLabel }
@ps $e = evtx-rec tc/rdp-1149-nhieu-may.evtx | ConvertFrom-Json | Sort-Object t; $e | ForEach-Object { '{0}  {1,-24} user={2} từ {3}' -f $_.t.ToString('HH:mm:ss.fff'), $_.may, $_.data.Param1, $_.data.Param3 }; '{0} máy trong {1:N1} giây' -f $e.Count, ($e[-1].t - $e[0].t).TotalSeconds
@ps evtx-rec tc/rdp-4825.evtx | ConvertFrom-Json | ForEach-Object { '{0}  {1}  {2}\{3} từ {4} — bị từ chối RDP' -f $_.t.ToString('s'), $_.id, $_.data.AccountDomain, $_.data.AccountName, $_.data.ClientAddress }
